import asyncio
import json
from typing import Any, Dict
import httpx
from fastmcp import Server


async def create_openapi_mcp_server(
    openapi_spec: Dict[str, Any],
    client: httpx.AsyncClient,
    server_name: str = "openapi-server"
) -> Server:
    """
    Generate an MCP server from an OpenAPI 3.0 specification.

    Args:
        openapi_spec: OpenAPI 3.0 spec as a Python dict
        client: Configured httpx.AsyncClient with base URL set
        server_name: Name for the MCP server

    Returns:
        A FastMCP Server with tools mirroring the OpenAPI operations
    """
    server = Server(server_name)

    paths = openapi_spec.get("paths", {})

    for path, path_item in paths.items():
        for method, operation in path_item.items():
            if method not in {"get", "post", "put", "delete", "patch", "head", "options"}:
                continue

            operation_id = operation.get("operationId", f"{method}_{path.replace('/', '_')}")
            summary = operation.get("summary", f"{method.upper()} {path}")
            parameters = operation.get("parameters", [])
            request_body = operation.get("requestBody", {})

            # Create handler function with closure to capture values
            def make_handler(http_method: str, url_path: str, params_spec: list, body_spec: dict):
                async def handler(**kwargs) -> str:
                    actual_path = url_path
                    query_params = {}
                    body_data = None

                    # Process parameters
                    for param in params_spec:
                        param_name = param.get("name")
                        param_in = param.get("in")

                        if param_name and param_name in kwargs:
                            value = kwargs[param_name]
                            if param_in == "path":
                                actual_path = actual_path.replace(f"{{{param_name}}}", str(value))
                            elif param_in == "query":
                                query_params[param_name] = value

                    # Handle request body
                    if "body_data" in kwargs and body_spec:
                        body_data = kwargs["body_data"]

                    try:
                        response = await client.request(
                            method=http_method.upper(),
                            url=actual_path,
                            params=query_params if query_params else None,
                            json=body_data if isinstance(body_data, dict) else None,
                            content=body_data if isinstance(body_data, (str, bytes)) else None
                        )
                        response.raise_for_status()

                        content_type = response.headers.get("content-type", "")
                        try:
                            data = response.json()
                        except:
                            data = response.text

                        return json.dumps({
                            "status": response.status_code,
                            "data": data
                        })
                    except httpx.HTTPError as e:
                        return json.dumps({
                            "error": str(e),
                            "status": getattr(e.response, "status_code", None)
                        })
                    except Exception as e:
                        return json.dumps({"error": str(e)})

                return handler

            # Build input schema from parameters
            properties = {}
            required = []

            for param in parameters:
                param_name = param.get("name")
                param_schema = param.get("schema", {})
                param_required = param.get("required", False)

                properties[param_name] = {
                    "type": param_schema.get("type", "string"),
                    "description": param.get("description", "")
                }

                if param_required:
                    required.append(param_name)

            # Add body parameter if request body exists
            if request_body:
                properties["body_data"] = {
                    "type": "object",
                    "description": "Request body"
                }
                if request_body.get("required"):
                    required.append("body_data")

            # Create handler and register tool
            handler = make_handler(method, path, parameters, request_body)
            handler.__name__ = operation_id

            input_schema = {
                "type": "object",
                "properties": properties,
                "required": required
            }

            server.add_tool(
                name=operation_id,
                description=summary,
                inputSchema=input_schema,
                func=handler
            )

    return server


async def main():
    # Example OpenAPI specification
    openapi_spec = {
        "openapi": "3.0.0",
        "info": {"title": "Example API", "version": "1.0.0"},
        "paths": {
            "/posts/{post_id}": {
                "get": {
                    "operationId": "getPost",
                    "summary": "Retrieve a post by ID",
                    "parameters": [
                        {
                            "name": "post_id",
                            "in": "path",
                            "required": True,
                            "schema": {"type": "string"}
                        }
                    ]
                }
            },
            "/posts": {
                "get": {
                    "operationId": "listPosts",
                    "summary": "List all posts",
                    "parameters": [
                        {
                            "name": "limit",
                            "in": "query",
                            "required": False,
                            "schema": {"type": "integer"}
                        }
                    ]
                },
                "post": {
                    "operationId": "createPost",
                    "summary": "Create a new post",
                    "parameters": [],
                    "requestBody": {"required": True}
                }
            }
        }
    }

    # Create client and server
    async with httpx.AsyncClient(base_url="https://api.example.com") as client:
        server = await create_openapi_mcp_server(openapi_spec, client)

        # Server is ready with tools mapped from OpenAPI spec
        tools = server.list_tools()
        print(f"Created MCP server with {len(tools)} tools:")
        for tool in tools:
            print(f"  - {tool.name}: {tool.description}")


if __name__ == "__main__":
    asyncio.run(main())

